public class Main {
    public static void main(String[] args) {
        int total = 25000;
        int bayar = 30000;
        if (bayar < total) {
            System.out.println("Uang kurang!");
        }
        if (bayar >= total) {
            System.out.println("Uang cukup");
        }
    }
}

